func (v FilterValue) Equal(o attr.Value) bool {
	other, ok := o.(FilterValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Attribute.Equal(other.Attribute) {
		return false
	}

	if !v.CohortMembership.Equal(other.CohortMembership) {
		return false
	}

	if !v.OutcomePercentile.Equal(other.OutcomePercentile) {
		return false
	}

	if !v.OutcomeProbability.Equal(other.OutcomeProbability) {
		return false
	}

	if !v.OutcomeScore.Equal(other.OutcomeScore) {
		return false
	}

	if !v.Persona.Equal(other.Persona) {
		return false
	}

	if !v.RecommenderRank.Equal(other.RecommenderRank) {
		return false
	}

	if !v.RecommenderUncalibratedProbability.Equal(other.RecommenderUncalibratedProbability) {
		return false
	}

	if !v.Trait.Equal(other.Trait) {
		return false
	}

	return true
}

