func (v AttributeValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var inVal basetypes.ListValue
	switch {
	case v.In.IsUnknown():
		inVal = types.ListUnknown(types.StringType)
	case v.In.IsNull():
		inVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		inVal, d = types.ListValue(types.StringType, v.In.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"_eq":  basetypes.StringType{},
			"_gt":  basetypes.NumberType{},
			"_gte": basetypes.NumberType{},
			"_in": basetypes.ListType{
				ElemType: types.StringType,
			},
			"_lt":      basetypes.NumberType{},
			"_lte":     basetypes.NumberType{},
			"_matches": basetypes.StringType{},
			"_neq":     basetypes.StringType{},
			"_nin": basetypes.ListType{
				ElemType: types.StringType,
			},
			"_nnull": basetypes.BoolType{},
			"_null":  basetypes.BoolType{},
			"name":   basetypes.StringType{},
		}), diags
	}

	var ninVal basetypes.ListValue
	switch {
	case v.Nin.IsUnknown():
		ninVal = types.ListUnknown(types.StringType)
	case v.Nin.IsNull():
		ninVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		ninVal, d = types.ListValue(types.StringType, v.Nin.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"_eq":  basetypes.StringType{},
			"_gt":  basetypes.NumberType{},
			"_gte": basetypes.NumberType{},
			"_in": basetypes.ListType{
				ElemType: types.StringType,
			},
			"_lt":      basetypes.NumberType{},
			"_lte":     basetypes.NumberType{},
			"_matches": basetypes.StringType{},
			"_neq":     basetypes.StringType{},
			"_nin": basetypes.ListType{
				ElemType: types.StringType,
			},
			"_nnull": basetypes.BoolType{},
			"_null":  basetypes.BoolType{},
			"name":   basetypes.StringType{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"_eq":  basetypes.StringType{},
		"_gt":  basetypes.NumberType{},
		"_gte": basetypes.NumberType{},
		"_in": basetypes.ListType{
			ElemType: types.StringType,
		},
		"_lt":      basetypes.NumberType{},
		"_lte":     basetypes.NumberType{},
		"_matches": basetypes.StringType{},
		"_neq":     basetypes.StringType{},
		"_nin": basetypes.ListType{
			ElemType: types.StringType,
		},
		"_nnull": basetypes.BoolType{},
		"_null":  basetypes.BoolType{},
		"name":   basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"_eq":      v.Eq,
			"_gt":      v.Gt,
			"_gte":     v.Gte,
			"_in":      inVal,
			"_lt":      v.Lt,
			"_lte":     v.Lte,
			"_matches": v.Matches,
			"_neq":     v.Neq,
			"_nin":     ninVal,
			"_nnull":   v.Nnull,
			"_null":    v.Null,
			"name":     v.Name,
		})

	return objVal, diags
}

func (v AttributeValue) Equal(o attr.Value) bool {
	other, ok := o.(AttributeValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Eq.Equal(other.Eq) {
		return false
	}

	if !v.Gt.Equal(other.Gt) {
		return false
	}

	if !v.Gte.Equal(other.Gte) {
		return false
	}

	if !v.In.Equal(other.In) {
		return false
	}

	if !v.Lt.Equal(other.Lt) {
		return false
	}

	if !v.Lte.Equal(other.Lte) {
		return false
	}

	if !v.Matches.Equal(other.Matches) {
		return false
	}

	if !v.Neq.Equal(other.Neq) {
		return false
	}

	if !v.Nin.Equal(other.Nin) {
		return false
	}

	if !v.Nnull.Equal(other.Nnull) {
		return false
	}

	if !v.Null.Equal(other.Null) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	return true
}

