func NewIdentifiedValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (IdentifiedValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing IdentifiedValue Attribute Value",
				"While creating a IdentifiedValue value, a missing attribute value was detected. "+
					"A IdentifiedValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("IdentifiedValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid IdentifiedValue Attribute Type",
				"While creating a IdentifiedValue value, an invalid attribute value was detected. "+
					"A IdentifiedValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("IdentifiedValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("IdentifiedValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra IdentifiedValue Attribute Value",
				"While creating a IdentifiedValue value, an extra attribute value was detected. "+
					"A IdentifiedValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra IdentifiedValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewIdentifiedValueUnknown(), diags
	}

	aggregateAttribute, ok := attributes["aggregate"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`aggregate is missing from object`)

		return NewIdentifiedValueUnknown(), diags
	}

	aggregateVal, ok := aggregateAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`aggregate expected to be basetypes.StringValue, was: %T`, aggregateAttribute))
	}

	imputePayloadAttribute, ok := attributes["impute_payload"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`impute_payload is missing from object`)

		return NewIdentifiedValueUnknown(), diags
	}

	imputePayloadVal, ok := imputePayloadAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`impute_payload expected to be basetypes.ListValue, was: %T`, imputePayloadAttribute))
	}

	outputMultipleIdentitiesAttribute, ok := attributes["output_multiple_identities"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`output_multiple_identities is missing from object`)

		return NewIdentifiedValueUnknown(), diags
	}

	outputMultipleIdentitiesVal, ok := outputMultipleIdentitiesAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`output_multiple_identities expected to be basetypes.BoolValue, was: %T`, outputMultipleIdentitiesAttribute))
	}

	transformPresetAttribute, ok := attributes["transform_preset"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`transform_preset is missing from object`)

		return NewIdentifiedValueUnknown(), diags
	}

	transformPresetVal, ok := transformPresetAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`transform_preset expected to be basetypes.StringValue, was: %T`, transformPresetAttribute))
	}

	if diags.HasError() {
		return NewIdentifiedValueUnknown(), diags
	}

	return IdentifiedValue{
		Aggregate:                aggregateVal,
		ImputePayload:            imputePayloadVal,
		OutputMultipleIdentities: outputMultipleIdentitiesVal,
		TransformPreset:          transformPresetVal,
		state:                    attr.ValueStateKnown,
	}, diags
}

func NewIdentifiedValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) IdentifiedValue {
	object, diags := NewIdentifiedValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewIdentifiedValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t IdentifiedType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewIdentifiedValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewIdentifiedValueUnknown(), nil
	}

	if in.IsNull() {
		return NewIdentifiedValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewIdentifiedValueMust(IdentifiedValue{}.AttributeTypes(ctx), attributes), nil
}

