type IdentifiedValue struct {
	Aggregate                basetypes.StringValue `tfsdk:"aggregate"`
	ImputePayload            basetypes.ListValue   `tfsdk:"impute_payload"`
	OutputMultipleIdentities basetypes.BoolValue   `tfsdk:"output_multiple_identities"`
	TransformPreset          basetypes.StringValue `tfsdk:"transform_preset"`
	state                    attr.ValueState
}

func (v IdentifiedValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 4)

	var val tftypes.Value
	var err error

	attrTypes["aggregate"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["impute_payload"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["output_multiple_identities"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["transform_preset"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 4)

		val, err = v.Aggregate.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["aggregate"] = val

		val, err = v.ImputePayload.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["impute_payload"] = val

		val, err = v.OutputMultipleIdentities.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["output_multiple_identities"] = val

		val, err = v.TransformPreset.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["transform_preset"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

