func (v ReferencedValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var reference basetypes.ObjectValue

	if v.Reference.IsNull() {
		reference = types.ObjectNull(
			ReferenceValue{}.AttributeTypes(ctx),
		)
	}

	if v.Reference.IsUnknown() {
		reference = types.ObjectUnknown(
			ReferenceValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Reference.IsNull() && !v.Reference.IsUnknown() {
		reference = types.ObjectValueMust(
			ReferenceValue{}.AttributeTypes(ctx),
			v.Reference.Attributes(),
		)
	}

	var imputePayloadVal basetypes.ListValue
	switch {
	case v.ImputePayload.IsUnknown():
		imputePayloadVal = types.ListUnknown(types.StringType)
	case v.ImputePayload.IsNull():
		imputePayloadVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		imputePayloadVal, d = types.ListValue(types.StringType, v.ImputePayload.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"impute_payload": basetypes.ListType{
				ElemType: types.StringType,
			},
			"output_multiple_identities": basetypes.BoolType{},
			"reference": basetypes.ObjectType{
				AttrTypes: ReferenceValue{}.AttributeTypes(ctx),
			},
			"reference_dataset_id": basetypes.StringType{},
			"transform_preset":     basetypes.StringType{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"impute_payload": basetypes.ListType{
			ElemType: types.StringType,
		},
		"output_multiple_identities": basetypes.BoolType{},
		"reference": basetypes.ObjectType{
			AttrTypes: ReferenceValue{}.AttributeTypes(ctx),
		},
		"reference_dataset_id": basetypes.StringType{},
		"transform_preset":     basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"impute_payload":             imputePayloadVal,
			"output_multiple_identities": v.OutputMultipleIdentities,
			"reference":                  reference,
			"reference_dataset_id":       v.ReferenceDatasetId,
			"transform_preset":           v.TransformPreset,
		})

	return objVal, diags
}

func (v ReferencedValue) Equal(o attr.Value) bool {
	other, ok := o.(ReferencedValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.ImputePayload.Equal(other.ImputePayload) {
		return false
	}

	if !v.OutputMultipleIdentities.Equal(other.OutputMultipleIdentities) {
		return false
	}

	if !v.Reference.Equal(other.Reference) {
		return false
	}

	if !v.ReferenceDatasetId.Equal(other.ReferenceDatasetId) {
		return false
	}

	if !v.TransformPreset.Equal(other.TransformPreset) {
		return false
	}

	return true
}

